  uh_bc_yon_kisi: { tr: 'Sizin B (İlahi) Kuyruğunuz ↔ Partnerinizin C (Karmik Kuyruk) Kuyruğu', en: 'Your B (Divine) Tail and Your Partner\'s C (Karmic Tail)' },
