  uh_bd_yon_partner: { tr: 'Partnerinizin B (İlahi) Kuyruğu ↔ Sizin D (Karmik Ders) Kuyruğunuz', en: 'Your Partner\'s B (Divine) Tail and Your D (Karmic Lesson) Tail' },
